<?php declare(strict_types=1); namespace App\Models; use Illuminate\Database\Eloquent\Model; class VaccinationCard extends Model { protected $guarded=[]; protected $casts=["ocr_result"=>"array","extracted_vaccines"=>"array","expires_at"=>"date","alerts_sent"=>"boolean"]; public function pet(){return $this->belongsTo(Pet::class);} public function hotel(){return $this->belongsTo(Hotel::class);} public function reservation(){return $this->belongsTo(Reservation::class);} public function uploader(){return $this->belongsTo(User::class,"uploaded_by");} }